export const lessons=[
{id:'hello',icon:'👋',title:'Your first hello',subtitle:'Meet someone. Make a little connection.',category:'First steps',minutes:5,words:[['Hallo','Hello'],['Guten Morgen','Good morning'],['Guten Tag','Good day / hello'],['Guten Abend','Good evening'],['Tschüss','Bye'],['Auf Wiedersehen','Goodbye (formal)']],rule:'German has friendly and formal ways to greet people. Hallo works in everyday conversation. Guten Tag is a polite daytime greeting. All German nouns begin with a capital letter, including Morgen, Tag and Abend.',example:['Hallo! Ich heiße Anna.','Hello! My name is Anna.'],quiz:[['How do you say “Hello”?','Hallo'],['Say “Good morning”.','Guten Morgen'],['Say an informal “Bye”.','Tschüss']],scene:[['Anna','cheerful','Hallo! Ich heiße Anna.','Hello! My name is Anna.'],['Ben','friendly','Hallo, Anna! Ich bin Ben.','Hello, Anna! I am Ben.']]},
{id:'sounds',icon:'🔤',title:'Meet the German sounds',subtitle:'Give ä, ö, ü and ß a little attention.',category:'First steps',minutes:8,words:[['der Apfel','the apple'],['die Äpfel','the apples'],['schön','beautiful / nice'],['grün','green'],['die Straße','the street'],['ich','I']],rule:'Ä, ö and ü are separate vowel sounds, not decorative letters. For ü, say a long “ee” while rounding your lips. For ö, keep a tongue position like “eh” and round your lips. ß represents a sharp s sound, not a b. Use the Sound studio for audio and mouth-position guidance.',example:['Die Straße ist schön.','The street is beautiful.'],quiz:[['Write the German word for “green”.','grün'],['Write the German word for “beautiful”.','schön'],['Write “the street”, including ß.','die Straße']],scene:[['Anna','curious','Ist die Straße schön?','Is the street beautiful?'],['Ben','pleased','Ja, sie ist sehr schön.','Yes, it is very beautiful.']]},
{id:'introductions',icon:'💬',title:'A little about you',subtitle:'Your name, your home, your first conversation.',category:'First conversations',minutes:7,words:[['Ich heiße …','My name is …'],['Wie heißt du?','What is your name? (informal)'],['Ich komme aus Indien.','I come from India.'],['Woher kommst du?','Where do you come from?'],['Ich wohne in Berlin.','I live in Berlin.'],['Freut mich!','Nice to meet you!']],rule:'Use ich for “I” and du for an informal “you”. A regular verb usually adds -e with ich: ich wohne; with du, -st: du wohnst. In a question like Woher kommst du?, the question word comes first and the conjugated verb second. Formal “you” is Sie: Wie heißen Sie?',example:['Ich heiße Sam und ich wohne in Berlin.','My name is Sam and I live in Berlin.'],quiz:[['Complete: Ich ___ in Berlin. (wohnen)','wohne'],['Complete: Woher ___ du? (kommen)','kommst'],['Write “Nice to meet you!”','Freut mich']],scene:[['Anna','curious','Wie heißt du?','What is your name?'],['Ben','friendly','Ich heiße Ben. Freut mich!','My name is Ben. Nice to meet you!']]},
{id:'numbers',icon:'🔢',title:'Numbers & little details',subtitle:'Count, share your age, and talk prices.',category:'Everyday essentials',minutes:7,words:[['eins, zwei, drei','one, two, three'],['vier, fünf, sechs','four, five, six'],['sieben, acht, neun, zehn','seven, eight, nine, ten'],['elf, zwölf','eleven, twelve'],['zwanzig','twenty'],['Wie viel kostet das?','How much does that cost?']],rule:'From 21 onward, German puts the unit before the tens: einundzwanzig = one-and-twenty (21), zweiunddreißig = two-and-thirty (32). Age uses sein: Ich bin zwanzig Jahre alt. Do not use haben for age. Pronounce z like “ts”.',example:['Ich bin einundzwanzig Jahre alt.','I am twenty-one years old.'],quiz:[['Write the German word for “five”.','fünf'],['Write the German word for “twenty”.','zwanzig'],['Complete: Ich ___ zwanzig Jahre alt.','bin']],scene:[['Anna','curious','Wie viel kostet das?','How much does that cost?'],['Ben','neutral','Das kostet zwölf Euro.','That costs twelve euros.']]},
{id:'articles',icon:'🧩',title:'Der, die, das',subtitle:'Make friends with nouns and their articles.',category:'Build your sentences',minutes:9,words:[['der Tisch','the table'],['die Tasche','the bag'],['das Buch','the book'],['die Bücher','the books'],['ein Kaffee','a coffee'],['eine Frage','a question']],rule:'Every noun has grammatical gender: der (masculine), die (feminine), das (neuter). Memorize the article with each noun; meaning is not a reliable guide. Plural “the” is always die in the nominative. “A/an” is ein for masculine and neuter, eine for feminine. A case changes the article according to the noun’s job in the sentence.',example:['Das ist ein Buch. Die Bücher sind neu.','That is a book. The books are new.'],quiz:[['Add the article: ___ Buch','das'],['Add the article: ___ Tasche','die'],['Write “a question”.','eine Frage']],scene:[['Anna','curious','Ist das ein Buch?','Is that a book?'],['Ben','neutral','Ja, das ist mein Buch.','Yes, that is my book.']]},
{id:'cafe',icon:'☕',title:'At your favourite café',subtitle:'Order something lovely, politely.',category:'Out in the world',minutes:8,words:[['Ich möchte einen Kaffee.','I would like a coffee.'],['das Wasser','the water'],['der Tee','the tea'],['die Rechnung','the bill'],['bitte','please / you are welcome'],['danke','thank you']],rule:'Ich möchte … is a useful polite request. A masculine direct object changes ein to einen: einen Kaffee. Feminine eine and neuter ein stay the same in the accusative. Bitte can mean “please” or “you’re welcome”. Learn the full phrase first, then notice the grammar.',example:['Ich möchte einen Tee, bitte.','I would like a tea, please.'],quiz:[['Write the German for “thank you”.','danke'],['Complete: Ich möchte ___ Kaffee.','einen'],['Write “the bill”.','die Rechnung']],scene:[['Anna','friendly','Guten Tag! Einen Kaffee, bitte.','Hello! A coffee, please.'],['Ben','friendly','Gerne. Sonst noch etwas?','Of course. Anything else?'],['Anna','pleased','Nein, danke.','No, thank you.']]},
{id:'people',icon:'🏡',title:'People & everyday life',subtitle:'Talk about your people and your day.',category:'Build your sentences',minutes:8,words:[['die Familie','the family'],['mein Freund','my friend (male)'],['meine Freundin','my friend (female)'],['Ich lerne Deutsch.','I am learning German.'],['Ich stehe früh auf.','I get up early.'],['Wir kaufen ein.','We go shopping.']],rule:'A statement keeps the conjugated verb in position two: Heute lerne ich Deutsch. Separable verbs place their prefix at the end: aufstehen → Ich stehe früh auf. Possessives follow gender: mein Vater, meine Mutter, mein Kind. Ich bin, du bist, er/sie/es ist, wir sind, ihr seid, sie/Sie sind are the forms of sein (to be).',example:['Heute stehe ich früh auf und lerne Deutsch.','Today I get up early and study German.'],quiz:[['Complete: Heute ___ ich Deutsch. (lernen)','lerne'],['Complete: Ich stehe früh ___.','auf'],['Complete: Wir ___ müde. (sein)','sind']],scene:[['Anna','curious','Was machst du heute?','What are you doing today?'],['Ben','neutral','Ich kaufe ein und lerne Deutsch.','I go shopping and study German.']]},
{id:'time',icon:'🕒',title:'Time for a plan',subtitle:'Days, times, and meeting up.',category:'Everyday essentials',minutes:7,words:[['heute','today'],['morgen','tomorrow'],['gestern','yesterday'],['am Montag','on Monday'],['um neun Uhr','at nine o’clock'],['im Sommer','in summer']],rule:'Use am with days and parts of the day, um with exact clock times, im with months and seasons. Morgen as a noun means morning: am Morgen. Lowercase morgen means tomorrow. The days are Montag, Dienstag, Mittwoch, Donnerstag, Freitag, Samstag and Sonntag.',example:['Wir treffen uns am Montag um neun Uhr.','We meet on Monday at nine o’clock.'],quiz:[['Complete: ___ Montag','am'],['Complete: ___ neun Uhr','um'],['Translate “tomorrow”.','morgen']],scene:[['Anna','curious','Wann treffen wir uns?','When shall we meet?'],['Ben','friendly','Morgen um neun Uhr.','Tomorrow at nine o’clock.']]},
{id:'directions',icon:'🧭',title:'Find your way',subtitle:'Ask for help and explore a new city.',category:'Out in the world',minutes:9,words:[['Wo ist der Bahnhof?','Where is the railway station?'],['links','left'],['rechts','right'],['geradeaus','straight ahead'],['die Ampel','the traffic light'],['neben der Bank','next to the bank']],rule:'Use wo for a location, wohin for a destination, woher for an origin. Polite commands use verb + Sie: Gehen Sie geradeaus. Biegen Sie links ab. For a location, in/auf/neben and the other two-way prepositions take dative: neben dem Bahnhof, in der Stadt. For movement into a destination, use accusative: in die Stadt.',example:['Gehen Sie geradeaus. Der Bahnhof ist neben der Bank.','Go straight ahead. The station is next to the bank.'],quiz:[['Translate “right”.','rechts'],['Complete the polite command: Gehen ___ geradeaus.','Sie'],['Complete: neben ___ Bank','der']],scene:[['Anna','curious','Entschuldigung, wo ist der Bahnhof?','Excuse me, where is the station?'],['Ben','helpful','Gehen Sie geradeaus und dann links.','Go straight ahead and then left.']]},
{id:'shopping',icon:'🛍️',title:'Something that suits you',subtitle:'Shops, clothes, and sharing an opinion.',category:'Out in the world',minutes:8,words:[['die Bäckerei','the bakery'],['die Apotheke','the pharmacy'],['der Mantel','the coat'],['die Hose','the trousers'],['Das gefällt mir.','I like that.'],['Das ist zu teuer.','That is too expensive.']],rule:'Gefallen and passen use a dative person: Das gefällt mir (I like that), Die Hose passt dir (the trousers fit you). Dative pronouns are mir, dir, ihm, ihr, ihm, uns, euch, ihnen, Ihnen. “Which” changes with case: Welcher Mantel ist schön? Welchen Mantel kaufst du?',example:['Dieser Mantel gefällt mir, aber er ist zu teuer.','I like this coat, but it is too expensive.'],quiz:[['Complete: Das gefällt ___. (ich)','mir'],['Write “the pharmacy”.','die Apotheke'],['Complete: ___ Mantel kaufst du? (which)','Welchen']],scene:[['Anna','curious','Wie findest du diesen Mantel?','What do you think of this coat?'],['Ben','pleased','Er ist schön, aber sehr teuer.','It is beautiful, but very expensive.']]},
{id:'travel',icon:'🚆',title:'A little adventure',subtitle:'Travel, weather, and making plans.',category:'Out in the world',minutes:9,words:[['Ich fahre ans Meer.','I am going to the seaside.'],['Es ist sonnig.','It is sunny.'],['Es regnet.','It is raining.'],['ein Zimmer buchen','book a room'],['Ich muss gehen.','I have to go.'],['Darf ich hier sitzen?','May I sit here?']],rule:'Modal verbs frame an infinitive at the end: Ich muss gehen. Ich darf hier sitzen. Du sollst lernen. Müssen means have to, dürfen means be allowed to, sollen reports an instruction or expectation. Du darfst nicht means you must not; du musst nicht means you do not have to. Most cities and countries take nach: nach Berlin, nach Deutschland.',example:['Im Sommer möchte ich ans Meer fahren.','In summer I would like to travel to the seaside.'],quiz:[['Translate “It is raining.”','Es regnet'],['Complete: Du ___ hier nicht rauchen. (dürfen)','darfst'],['Complete: Ich muss heute ___. (to study)','lernen']],scene:[['Anna','excited','Morgen fahren wir ans Meer!','Tomorrow we are going to the seaside!'],['Ben','pleased','Toll! Das Wetter ist sonnig.','Great! The weather is sunny.']]},
{id:'yesterday',icon:'📷',title:'Tell a little story',subtitle:'Your first conversation about yesterday.',category:'Keep the conversation going',minutes:10,words:[['Ich habe gelernt.','I studied.'],['Wir sind gefahren.','We travelled.'],['Ich habe gegessen.','I ate.'],['Sie ist gekommen.','She came.'],['Es war schön.','It was lovely.'],['Was hast du gemacht?','What did you do?']],rule:'The Perfekt uses haben or sein plus a past participle at the end. Most verbs use haben: Ich habe gelernt. Travel and certain changes use sein: Ich bin nach Hause gegangen. Regular participles often use ge-…-t: machen → gemacht. Learn irregular forms: essen → gegessen; kommen → gekommen; fahren → gefahren. Und, oder and aber join clauses without moving the verb to the end.',example:['Gestern habe ich Deutsch gelernt und einen Film gesehen.','Yesterday I studied German and watched a film.'],quiz:[['Complete: Ich ___ Deutsch gelernt.','habe'],['Complete: Wir ___ nach Berlin gefahren.','sind'],['Give the participle of machen.','gemacht']],scene:[['Anna','curious','Was hast du gestern gemacht?','What did you do yesterday?'],['Ben','pleased','Ich habe einen Film gesehen. Es war schön.','I watched a film. It was lovely.']]}
];
export const sounds=[
['Ä','ä','Tongue forward, lips relaxed. A long ä is like an open “eh”; listen rather than relying on English spelling.','Äpfel','apples'],['Ö','ö','Start with an “eh” tongue position, then round your lips without moving your tongue back.','schön','beautiful'],['Ü','ü','Say a long “ee”, hold your tongue there, and round your lips as if saying “oo”.','grün','green'],['ß','Eszett','This is a sharp, unvoiced s, as in “see”. It is not a b. The letter name is Eszett.','Straße','street'],['ch','ich','After front vowels (as in ich), raise the tongue toward the hard palate and let air pass softly. After a, o, u (as in Bach), the sound is farther back.','ich','I'],['sch','Schule','A sh sound, similar to “shoe”. Keep the air flowing.','Schule','school'],['ei','ein','A vowel glide like English “eye”.','ein','one / a'],['ie','Liebe','A long ee sound, as in “see”. Notice the order: ie, not ei.','Liebe','love'],['eu / äu','heute','A vowel glide similar to “oy” in “boy”.','heute','today'],['z','Zeit','Pronounce ts together, like the end of “cats”.','Zeit','time'],['w','Wasser','Usually like an English v. Touch the lower lip gently to the upper teeth.','Wasser','water'],['v','Vater','Often f in native words like Vater, but v in many loanwords. Learn each word with audio.','Vater','father'],['j','ja','Like English y in “yes”.','ja','yes'],['sp / st','Straße','At the beginning of many native syllables, sp sounds shp and st sounds sht.','sprechen','speak']
];
